#!/usr/bin/env python3
"""Create the lead's code-review issues in kartalbas/coder-shop with gh (problem, where, how to see it,
expected behaviour — no prescribed fix: the coder finds the solution)."""
import subprocess, sys, tempfile

REPO = "kartalbas/coder-shop"
FOOT = "\n\n---\n_Found in the lead's code review (2026-10-17), verified against the code._"

def issue(title, labels, problem, where, see, expected):
    body = f"**Problem**\n{problem}\n\n**Where**\n{where}\n\n**How to see it**\n{see}\n\n**Expected behaviour**\n{expected}{FOOT}"
    return (title, labels, body)

