if __name__ == "__main__":
    if "--dry" in sys.argv:
        for t, l, _ in I: print(f"[{', '.join(l)}] {t}")
        print(len(I), "issues"); sys.exit()
    for t, l, b in I:
        with tempfile.NamedTemporaryFile("w", suffix=".md", delete=False) as f:
            f.write(b)
        args = ["gh", "issue", "create", "-R", REPO, "--title", t, "--body-file", f.name]
        for x in l + ["from-review"]: args += ["--label", x]
        url = subprocess.run(args, capture_output=True, text=True).stdout.strip()
        print(url or f"FAILED: {t}", flush=True)
